import{_ as t,o as e,c as i,a2 as r}from"./chunks/framework.DajbkT6K.js";const l="/aibutler/docs/img/first-run-1.png",s="/aibutler/docs/img/first-run-2.png",m=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quickstart.md","filePath":"guide/quickstart.md"}'),o={name:"guide/quickstart.md"};function d(n,a,c,h,p,u){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>从下载到跟人格说上第一句话，大约十分钟。</p><h2 id="_1-下载安装包" tabindex="-1">1. 下载安装包 <a class="header-anchor" href="#_1-下载安装包" aria-label="Permalink to &quot;1. 下载安装包&quot;">​</a></h2><p>到 <a href="https://github.com/fantasyxxj/aibutler/releases" target="_blank" rel="noreferrer">Releases 页面</a> 下载最新版：</p><table tabindex="0"><thead><tr><th>你的电脑</th><th>下载这个</th></tr></thead><tbody><tr><td>Mac（M1 / M2 / M3 / M4 芯片）</td><td><code>aibutler-&lt;版本&gt;-arm64.dmg</code></td></tr><tr><td>Mac（Intel 芯片）</td><td><code>aibutler-&lt;版本&gt;-x64.dmg</code></td></tr><tr><td>Windows</td><td><code>aibutler-&lt;版本&gt;-setup.exe</code></td></tr></tbody></table><p>Mac 要 macOS 11 或更高。不知道自己是哪种芯片：点屏幕左上角 →「关于本机」，看「芯片」或「处理器」那一行。</p><h2 id="_2-安装" tabindex="-1">2. 安装 <a class="header-anchor" href="#_2-安装" aria-label="Permalink to &quot;2. 安装&quot;">​</a></h2><h3 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to &quot;Mac&quot;">​</a></h3><ol><li>双击 dmg，把「全能管家」拖进「应用程序」文件夹。</li><li>第一次打开时，系统可能提示「无法验证开发者」或「已损坏，无法打开」。这是因为安装包没有做苹果的付费签名，不是文件坏了。打开「终端」，粘贴下面这行回车，再去打开就好：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/全能管家.app</span></span></code></pre></div><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p>双击 <code>setup.exe</code> 安装。如果弹出「Windows 已保护你的电脑」，点「更多信息」→「仍要运行」。</p><h2 id="_3-第一次打开-先接上-ai" tabindex="-1">3. 第一次打开：先接上 AI <a class="header-anchor" href="#_3-第一次打开-先接上-ai" aria-label="Permalink to &quot;3. 第一次打开：先接上 AI&quot;">​</a></h2><p>第一次打开会看到两步引导。</p><p><img src="'+l+'" alt="第一步：先接上 AI"></p><p><strong>第一步「先接上 AI」</strong>：人格要接上 AI 模型才能说话，选一种你手上有的：</p><ul><li><strong>用 Claude 订阅</strong>：有 Claude Pro / Max 订阅就选这个。点「开启」，会先下载 Claude 的组件（约 110 MB），下载完重启，再点「登录 Claude」登录一次即可。</li><li><strong>用 API Key</strong>：Anthropic、OpenAI 兼容网关、国内大模型的 Key 都行。点「去添加 Key」，在弹出的系统设置里填好（怎么填见 <a href="/aibutler/docs/guide/models.html">接入模型</a>）。</li></ul><p>右上角可以切换界面语言。弄好后点「下一步」。</p><p><strong>第二步「给它起个名字」</strong>：这是你的第一个人格，默认叫「管家」，可以改成你喜欢的名字，再挑一个头像。模型从下拉里选；下拉里拉不到清单时，选「其它（手填）」自己填模型名。点「创建并开始」。</p><p><img src="'+s+'" alt="第二步：给它起个名字"></p><div class="tip custom-block"><p class="custom-block-title">「高级」里的两项</p><p>「引擎」和「人格资料放在」一般不用动。人格资料的位置建好之后就不能改了，如果你想放到别的盘，建之前在这里点「换个位置」。</p></div><h2 id="_4-说第一句话" tabindex="-1">4. 说第一句话 <a class="header-anchor" href="#_4-说第一句话" aria-label="Permalink to &quot;4. 说第一句话&quot;">​</a></h2><p>人格建好后就进入聊天窗口。随便说点什么，比如：</p><blockquote><p>你好，我叫小王，平时做设计，以后多帮我盯着点工作上的事。</p></blockquote><p>它会记住你说的，下次接着聊。接下来几件事，都可以直接问它：</p><ul><li>「你能帮我做什么？」</li><li>「我想在手机上也能找到你，怎么弄？」</li><li>「帮我做一个记账的小工具。」</li></ul><h2 id="_5-再建更多人格" tabindex="-1">5. 再建更多人格 <a class="header-anchor" href="#_5-再建更多人格" aria-label="Permalink to &quot;5. 再建更多人格&quot;">​</a></h2><p>点窗口上方的「人格 ▾」，选「＋ 新建人格…」，填个名字，点「创建并打开」。每个人格有自己的名字、记忆和模型，互不干扰，比如一个管工作、一个陪孩子学习。</p><p>同一个菜单里的「⚙ 管理人格…」打开人格管理：每张人格卡片右上角的「⋯」菜单可以「导出」人格，下方的「从文件导入…」可以把导出的人格装回来。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><p>先问人格。它连不上模型、说不了话时，看 <a href="/aibutler/docs/guide/models.html">接入模型</a> 里的常见问题。</p>',31)])])}const g=t(o,[["render",d]]);export{m as __pageData,g as default};
